int matchL[128], matchR[128];
int n, p;

bool bpm(int u) {
  for (int v = 0; v < p; v++)
    if (graph[u][v]) {
      if (seen[v])
        continue;
      seen[v] = true;

      if (matchR[v] < 0 || bpm(matchR[v])) {
        matchL[u] = v;
        matchR[v] = u;
        return true;
      }
    }
  return false;
}

